__NUXT_JSONP__("/inclusion/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{columnas:[{slug:"disaster_management_with_a_gender_perspective_a_historic_debt",title:"Disaster Management with a Gender Perspective: A Historic Debt",date:"2025-10-14T17:31:01.093Z",img:"https:\u002F\u002Fucarecdn.com\u002F24099e07-6fee-4e29-aea4-f6ecf79ee239\u002F","img-alt":"Manejo de desastres naturales",autor:h,medio:a,link:i,category:b,extracto:"Disasters disproportionately affect vulnerable groups, and women face a double burden: beyond the immediate crisis, they shoulder the majority of domestic and care work, protecting children, the elderly, and the sick. During and after emergencies, they manage scarce resources, search for water and food, and lead emotional and material reconstruction efforts.",toc:[],dir:c,path:"\u002Fcolumnas\u002Fdisaster_management_with_a_gender_perspective_a_historic_debt",extension:d,createdAt:"2025-11-25T01:24:03.235Z",updatedAt:"2025-11-25T01:24:03.236Z"},{slug:"la_persistente_brecha_salarial_de_genero_en_mexico",title:"La persistente brecha salarial de género en México",date:"2025-10-02T18:23:15.144Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd83edafc-5d49-426e-8b1d-d078246767ce\u002F",autor:j,medio:a,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fla-persistente-brecha-salarial-de-genero-en-mexico",category:b,extracto:"Cerrar la brecha salarial de género es un asunto de justicia social, una necesidad económica, una inversión en nuestro futuro y un pilar para construir un México más equitativo y próspero para todas y todos.",toc:[],dir:c,path:"\u002Fcolumnas\u002Fla_persistente_brecha_salarial_de_genero_en_mexico",extension:d,createdAt:k,updatedAt:k},{slug:"gestion_de_desastres_con_perspectiva_de_genero_una_deuda_pendiente",title:"Gestión de desastres con perspectiva de género, una deuda pendiente",date:"2025-09-05T22:36:42.835Z",img:"https:\u002F\u002Fucarecdn.com\u002Feb247842-237d-4d51-8ca0-561c63e51731\u002F",autor:h,medio:a,link:i,category:b,extracto:"Cuando ocurre un desastre, las mujeres cargan con un doble peso: además de la devastación, asumen la mayor parte del cuidado y la gestión de recursos, enfrentando riesgos adicionales como pérdida de autonomía, afectaciones a su salud y mayor vulnerabilidad a la violencia, sin que su voz sea escuchada en la reconstrucción de sus comunidades.",toc:[{id:"el-clima-cambia-la-vulnerabilidad-crece",depth:e,text:"El clima cambia, la vulnerabilidad crece"},{id:"el-rostro-de-la-devastación-tiene-género",depth:e,text:"El rostro de la devastación tiene género"},{id:"de-la-omisión-a-la-acción-políticas-públicas-con-perspectiva-de-género",depth:e,text:"De la omisión a la acción: políticas públicas con perspectiva de género"}],dir:c,path:"\u002Fcolumnas\u002Fgestion_de_desastres_con_perspectiva_de_genero_una_deuda_pendiente",extension:d,createdAt:l,updatedAt:l},{slug:"urge_dignificar_el_trabajo_del_hogar_remunerado_y_el_acceso_efectivo_a_la_seguridad_social",title:"Urge dignificar el trabajo del hogar remunerado y el acceso efectivo a la seguridad social",date:"2025-07-14T17:05:14.425Z",img:"https:\u002F\u002Fucarecdn.com\u002F4732284d-f643-4265-b88c-8c2b13c6fd53\u002F","img-alt":"Trabajadoras del hogar",autor:"Mónica Corona y Carmen Paola Avilés",medio:a,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ftrabajo-hogar-remunerado-seguridad-social",category:b,extracto:"Es nuestra responsabilidad como sociedad asegurar que quienes sostienen el bienestar de innumerables hogares gocen de los mismos derechos y la misma dignidad que cualquier otra persona trabajadora.",toc:[],dir:c,path:"\u002Fcolumnas\u002Furge_dignificar_el_trabajo_del_hogar_remunerado_y_el_acceso_efectivo_a_la_seguridad_social",extension:d,createdAt:m,updatedAt:m},{slug:"y_si_el_verdadero_lujo_fuera_el_trabajo_digno",title:"¿Y si el verdadero lujo fuera el trabajo digno?",date:"2025-05-19T17:41:24.996Z",img:"https:\u002F\u002Fucarecdn.com\u002Ffc776cbe-b469-43ed-a9f8-c861ff89fd15\u002F","img-alt":"Trabajadoras de maquila",autor:"Néstor Genis y Samantha Rivera",medio:a,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ftrabajo-digno",category:b,extracto:"Tal vez la clave no está en eliminar el deseo de lujo, sino en redefinirlo. ¿Y si el verdadero lujo no estuviera en lo que cuesta un producto, sino en cómo se produce? ¿Y si comenzamos a asociar el valor con la ética laboral y el prestigio con la justicia social?",toc:[{id:"trabajo-feminizado-y-precarizado",depth:e,text:"Trabajo feminizado y precarizado "},{id:"repensar-el-lujo",depth:e,text:"Repensar el lujo"},{id:"el-costo-de-la-dignidad",depth:e,text:"El costo de la dignidad "},{id:"la-tarea",depth:e,text:"La tarea "}],dir:c,path:"\u002Fcolumnas\u002Fy_si_el_verdadero_lujo_fuera_el_trabajo_digno",extension:d,createdAt:"2025-11-25T01:24:03.252Z",updatedAt:"2025-11-25T01:24:03.253Z"},{slug:"mujeres_migrantes_en_la_era_trump",title:"Mujeres migrantes en la era Trump",date:"2025-04-03T20:05:14.771Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc1ba6167-3069-49ec-9acd-defebd6432c7\u002F","img-alt":"Mujeres migrantes",autor:j,medio:a,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fmujeres-migrantes-era-trump",category:b,extracto:"A pesar de la creciente participación de las mujeres en los procesos migratorios, persiste su invisibilización como personas autónomas y que toman decisiones a lo largo de estos procesos. Esta situación se sustenta en prejuicios, normas y prácticas que perpetúan la discriminación y la subordinación de las mujeres en todos los ámbitos de la sociedad, profundizando las desigualdades.",toc:[],dir:c,path:"\u002Fcolumnas\u002Fmujeres_migrantes_en_la_era_trump",extension:d,createdAt:f,updatedAt:f},{slug:"como_fortalecer_la_perspectiva_de_genero_en_la_reforma_sobre_plataformas_digitales",title:"¿Cómo fortalecer la perspectiva de género en la reforma sobre plataformas digitales?",date:"2025-03-25T21:34:09.393Z",img:"https:\u002F\u002Fucarecdn.com\u002F162dcc2a-9b88-465b-8004-7d592449629d\u002F","img-alt":"Mujer repartidora",autor:"Ivette Pichardo, Ana Medina, Shaira Garduño y Néstor Genis",medio:a,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ffortalecer-perspectiva-genero-reforma-plataformas-digitales",category:b,extracto:"Para que la reforma a la Ley Federal del Trabajo sobre plataformas digitales sea verdaderamente justa e inclusiva no basta con reconocer la relación laboral; es imperativo garantizar que las mujeres puedan ejercer plenamente sus derechos, acceder a la seguridad social y trabajar en un entorno libre de violencia.",toc:[{id:"protocolos-de-prevención-y-atención-a-la-violencia-de-género",depth:g,text:"Protocolos de prevención y atención a la violencia de género"},{id:"acceso-y-pleno-ejercicio-de-prestaciones-laborales",depth:g,text:"Acceso y pleno ejercicio de prestaciones laborales"},{id:"incorporar-la-perspectiva-de-género-desde-el-diseño-de-la-prueba-piloto",depth:g,text:"Incorporar la perspectiva de género desde el diseño de la prueba piloto"}],dir:c,path:"\u002Fcolumnas\u002Fcomo_fortalecer_la_perspectiva_de_genero_en_la_reforma_sobre_plataformas_digitales",extension:d,createdAt:"2025-04-23T06:21:15.368Z",updatedAt:"2025-04-23T06:21:15.369Z"},{slug:"los_centros_de_educacion_y_cuidado_infantil_y_la_deuda_pendiente_con_las_mujeres_trabajadoras",title:"Los Centros de Educación y Cuidado Infantil y la deuda pendiente con las mujeres trabajadoras",date:"2025-02-26T17:16:41.593Z",img:"https:\u002F\u002Fucarecdn.com\u002F7756f7f8-97c8-4cd8-b5d2-41038ae15c55\u002F-\u002Fpreview\u002F","img-alt":"Centros ce cuidados",autor:"Marycarmen Rubalcava Oliveros",medio:a,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fcuidado-infantil-deuda-trabajadoras",category:b,extracto:"Para que los Centros de Educación y Cuidado Infantil tengan un impacto real en la vida de las mujeres trabajadoras deben formar parte de una estrategia más amplia que incluya trabajo digno, acceso a seguridad social y políticas que prevengan la explotación y la discriminación en el empleo.",toc:[],dir:c,path:"\u002Fcolumnas\u002Flos_centros_de_educacion_y_cuidado_infantil_y_la_deuda_pendiente_con_las_mujeres_trabajadoras",extension:d,createdAt:f,updatedAt:f}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("Animal Político","inclusion","\u002Fcolumnas",".md",2,"2025-04-23T06:21:15.370Z",3,"Néstor Genis y Luisa Crespi","https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fgestion-desastres-perspectiva-genero-deuda-pendiente","Mónica Corona","2025-11-25T01:24:03.244Z","2025-11-25T01:24:03.242Z","2025-11-25T01:24:03.251Z")));